#define main historical_main
#include "../s8n-cuda/main.cu"
#undef main
#include <vector>
#include <algorithm>
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
struct Case{int ranks;int*out;std::vector<int>expected;};
std::vector<int> sorted_oracle(std::vector<int>&xyz,int b,int n,int ranks){std::vector<int>out;for(int row=0;row<b;row++)for(int i=0;i<n;i++){int pos=3*(row*n+i),x=xyz[pos],y=xyz[pos+1],z=xyz[pos+2];std::vector<std::pair<long long,int>>buckets[8];for(int j=0;j<n;j++){if(i==j)continue;int q=3*(row*n+j),tx=xyz[q],ty=xyz[q+1],tz=xyz[q+2];long long d=(long long)(x-tx)*(x-tx)+(long long)(y-ty)*(y-ty)+(long long)(z-tz)*(z-tz);if(d>=512)continue;int oct=(tx>x)*4+(ty>y)*2+(tz>z);buckets[oct].push_back({d,j});}for(auto&bucket:buckets){std::sort(bucket.begin(),bucket.end());for(int k=0;k<ranks;k++)out.push_back(k<(int)bucket.size()?bucket[k].second:i);}}return out;}
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):100;if(repeat<1)return 2;int b=2,n=520;std::vector<int>xyz;for(int row=0;row<b;row++)for(int i=0;i<n;i++){int x=(i*7+row*3)%16-8,y=(i/16*5+row)%16-8,z=(i/128*3+i%3)%16-8;if(i==0){x=0;y=0;z=0;}else if(i==1){x=16;y=16;z=0;}else if(i==n-1){x=100;y=100;z=100;}xyz.insert(xyz.end(),{x,y,z});}int*dx;CK(cudaMalloc(&dx,xyz.size()*sizeof(int)));CK(cudaMemcpy(dx,xyz.data(),xyz.size()*sizeof(int),cudaMemcpyHostToDevice));std::vector<Case>cases;for(int ranks:{1,2,4}){Case c;c.ranks=ranks;c.expected=sorted_oracle(xyz,b,n,ranks);std::vector<int>ref(c.expected.size());if(ranks==1)cube_select(b,n,512,xyz.data(),ref.data());else if(ranks==2)cube_select_two(b,n,512,xyz.data(),ref.data());else cube_select_four(b,n,512,xyz.data(),ref.data());if(ref!=c.expected){puts("nativeCPU independent sort mismatch");return 3;}CK(cudaMalloc(&c.out,c.expected.size()*sizeof(int)));cases.push_back(c);}auto launch=[&](Case&c){if(c.ranks==1)k_cube_select<<<b,512>>>(b,n,512,dx,c.out);else if(c.ranks==2)k_cube_select_two<<<b,512>>>(b,n,512,dx,c.out);else k_cube_select_four<<<b,512>>>(b,n,512,dx,c.out);};for(auto&c:cases)launch(c);CK(cudaDeviceSynchronize());bool allok=true;for(int trial=1;trial<=5;trial++){double seconds=0;bool ok=true;std::vector<int>output;for(auto&c:cases){CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;rep++)launch(c);CK(cudaDeviceSynchronize());seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;std::vector<int>got(c.expected.size());CK(cudaMemcpy(got.data(),c.out,got.size()*sizeof(int),cudaMemcpyDeviceToHost));ok&=got==c.expected;output.insert(output.end(),got.begin(),got.end());}allok&=ok;char file[80];sprintf(file,"s8n_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(output.data(),sizeof(int),output.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":0,\"max_rel_error\":0,\"timing_region\":\"sum_all_three_complete_octant_neighbor_selections\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",output.size(),repeat,file,output.size());}for(auto&c:cases)CK(cudaFree(c.out));CK(cudaFree(dx));puts(allok?"PASS":"FAIL");return allok?0:1;}
